double area = (b - a) * fmax;
int count = 0;
std::mt19937 rng(seed);
std::uniform_real_distribution<double> x_dist(a, b);
std::uniform_real_distribution<double> y_dist(0, fmax);

for (int i = 0; i < n_points; i++) {
    double x = x_dist(rng);
    double y = y_dist(rng);
    if (y <= f(x)) {
        count++;
    }
}

return area * static_cast<double>(count) / n_points;

